"use strict";
import { useQuery } from "@tanstack/react-query";
const GAUGES_SUBGRAPH_URL = "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/abx-gauges/api";
const GET_AVAILABLE_GAUGES_QUERY = `
  query GetAvailableGauges {
    gauges(
      first: 100
      orderBy: totalWeight
      orderDirection: desc
      where: { isAlive: true }
    ) {
      id
      pool
      poolType
      isAlive
      totalWeight
      emissions
      bribeContract
      feeContract
      creator
      factory
      createdAtTimestamp
    }
  }
`;
const GET_GAUGE_DATA_QUERY = `
  query GetGaugeData($gaugeId: String!) {
    gauge(id: $gaugeId) {
      id
      pool
      poolType
      isAlive
      totalWeight
      emissions
      bribeContract
      feeContract
      creator
      factory
      createdAtTimestamp
      
      votes(first: 10, orderBy: timestamp, orderDirection: desc) {
        voter
        tokenId
        weight
        epoch
        timestamp
      }
      
      stakes(where: { amount_gt: "0" }) {
        user
        amount
        timestamp
      }
    }
  }
`;
const GET_USER_VOTES_QUERY = `
  query GetUserVotes($user: String!, $tokenId: String!) {
    votes(
      where: { 
        voter: $user,
        tokenId: $tokenId
      }
      orderBy: timestamp
      orderDirection: desc
    ) {
      id
      voter
      tokenId
      gauge {
        id
        pool
        poolType
        isAlive
        totalWeight
      }
      weight
      epoch
      timestamp
    }
  }
`;
const GET_CURRENT_EPOCH_QUERY = `
  query GetCurrentEpoch {
    gaugeGlobal(id: "global") {
      currentEpoch
      lastUpdatedTimestamp
    }
    
    votingEpochs(
      first: 1
      orderBy: startTime
      orderDirection: desc
    ) {
      id
      startTime
      endTime
      totalVotes
      totalGauges
      voters
    }
  }
`;
const GET_PROTOCOL_STATS_QUERY = `
  query GetProtocolStats {
    gaugeGlobal(id: "global") {
      totalGauges
      activeGauges
      totalStaked
      totalUsers
      totalVotes
      currentEpoch
      lastUpdatedTimestamp
    }
  }
`;
async function fetchDataFromSubgraph(query, variables = {}) {
  try {
    const response = await fetch(GAUGES_SUBGRAPH_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        query,
        variables
      })
    });
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }
    const data = await response.json();
    if (data.errors) {
      console.error("Gauge subgraph query errors:", data.errors);
      return null;
    }
    return data.data;
  } catch (error) {
    console.error("Failed to fetch gauge data:", error);
    return null;
  }
}
export function useAvailableGauges(enabled = true) {
  return useQuery({
    queryKey: ["available-gauges"],
    queryFn: async () => {
      const data = await fetchDataFromSubgraph(
        GET_AVAILABLE_GAUGES_QUERY
      );
      return data?.gauges || [];
    },
    enabled,
    refetchInterval: 6e4,
    // Refetch every minute
    staleTime: 3e4
    // Consider data stale after 30 seconds
  });
}
export function useGaugeData(gaugeId, enabled = true) {
  return useQuery({
    queryKey: ["gauge-data", gaugeId],
    queryFn: async () => {
      if (!gaugeId) return null;
      const data = await fetchDataFromSubgraph(
        GET_GAUGE_DATA_QUERY,
        { gaugeId: gaugeId.toLowerCase() }
      );
      return data?.gauge || null;
    },
    enabled: enabled && !!gaugeId,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    staleTime: 15e3
    // Consider data stale after 15 seconds
  });
}
export function useUserVotes(userAddress, tokenId, enabled = true) {
  return useQuery({
    queryKey: ["user-votes", userAddress, tokenId],
    queryFn: async () => {
      if (!userAddress || !tokenId) return [];
      const data = await fetchDataFromSubgraph(
        GET_USER_VOTES_QUERY,
        {
          user: userAddress.toLowerCase(),
          tokenId
        }
      );
      return data?.votes || [];
    },
    enabled: enabled && !!userAddress && !!tokenId,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    staleTime: 15e3
    // Consider data stale after 15 seconds
  });
}
export function useCurrentEpoch(enabled = true) {
  return useQuery({
    queryKey: ["current-epoch"],
    queryFn: async () => {
      const data = await fetchDataFromSubgraph(GET_CURRENT_EPOCH_QUERY);
      return {
        epoch: data?.votingEpochs?.[0] || null,
        protocolStats: data?.gaugeGlobal || null
      };
    },
    enabled,
    refetchInterval: 6e4,
    // Refetch every minute
    staleTime: 3e4
    // Consider data stale after 30 seconds
  });
}
export function useProtocolStats(enabled = true) {
  return useQuery({
    queryKey: ["protocol-stats"],
    queryFn: async () => {
      const data = await fetchDataFromSubgraph(GET_PROTOCOL_STATS_QUERY);
      return data?.gaugeGlobal || null;
    },
    enabled,
    refetchInterval: 6e4,
    // Refetch every minute
    staleTime: 3e4
    // Consider data stale after 30 seconds
  });
}
